+        /// <returns></returns>
+        private bool ShouldAutoPlugin(OrdrStat ordrStat, decimal balanceRMB, decimal paymentRate)
+        {
+            // 外币汇率差自动清账条件：
+            // 1. 已收完款（订单状态为已收全款）
+            // 2. 未收完款但总回款率达98% & 人民币余额<100元
+            return ordrStat.U_ReceivePayStatus == 1 ||
+                   (paymentRate >= 0.98m && Math.Abs(balanceRMB) < 100m);
+        }
+
+        /// <summary>
